class Solution {
public:
    int minimumLines(std::vector<std::vector<int>>& stockPrices) {
        std::sort(stockPrices.begin(), stockPrices.end(), [](const auto& a, const auto& b) {
            return a[0] < b[0];
        });
        int n = stockPrices.size();
        if (n <= 1) return 0;
        int lines = 1;
        for (int i = 2; i < n; ++i) {
            long long x1 = stockPrices[i - 2][0], y1 = stockPrices[i - 2][1];
            long long x2 = stockPrices[i - 1][0], y2 = stockPrices[i - 1][1];
            long long x3 = stockPrices[i][0], y3 = stockPrices[i][1];
            if ((y2 - y1) * (x3 - x2) != (y3 - y2) * (x2 - x1)) {
                lines++;
            }
        }
        return lines;
    }
};

class Solution {
    public int minimumLines(int[][] stockPrices) {
        java.util.Arrays.sort(stockPrices, (a, b) -> Integer.compare(a[0], b[0]));
        int n = stockPrices.length;
        if (n <= 1) return 0;
        int lines = 1;
        for (int i = 2; i < n; i++) {
            long x1 = stockPrices[i - 2][0], y1 = stockPrices[i - 2][1];
            long x2 = stockPrices[i - 1][0], y2 = stockPrices[i - 1][1];
            long x3 = stockPrices[i][0], y3 = stockPrices[i][1];
            if ((y2 - y1) * (x3 - x2) != (y3 - y2) * (x2 - x1)) {
                lines++;
            }
        }
        return lines;
    }
}

var minimumLines = function(stockPrices) {
    stockPrices.sort((a, b) => a[0] - b[0]);
    const n = stockPrices.length;
    if (n <= 1) return 0;
    let lines = 1;
    for (let i = 2; i < n; i++) {
        const x1 = BigInt(stockPrices[i - 2][0]), y1 = BigInt(stockPrices[i - 2][1]);
        const x2 = BigInt(stockPrices[i - 1][0]), y2 = BigInt(stockPrices[i - 1][1]);
        const x3 = BigInt(stockPrices[i][0]), y3 = BigInt(stockPrices[i][1]);
        if ((y2 - y1) * (x3 - x2) !== (y3 - y2) * (x2 - x1)) {
            lines++;
        }
    }
    return lines;
};
